type Screen = 'home' | 'product' | 'cart' | 'profile' | 'login' | 'register' | 'about' | 'tech' | 'collection' | 'support'
type Product = { id: number; name: string; category: string; price: number; image: string; label?: string; size: string; purpose: string; rating: string }
const products: Product[] = [
  { id: 1, name: 'Asphalt Basketball', category: 'Basketballs', price: 38945, image: '/images/collection-asphalt.png', label: 'NEW', size: '6', purpose: 'Outdoor', rating: '4.9' },
  { id: 2, name: 'Grip Basketball Socks', category: 'Accessories', price: 7000, image: '/images/collection-socks.png', label: 'BESTSELLER', size: 'M / L', purpose: 'All courts', rating: '4.9' },
  { id: 3, name: 'Pechenka Chocolate', category: 'Basketballs', price: 24990, image: '/images/collection-pechenka.png', size: '7', purpose: 'Indoor', rating: '5.0' },
  { id: 4, name: 'Wave Basketball', category: 'Basketballs', price: 30000, image: '/images/best-wave.png', label: 'NEW DROP', size: '6', purpose: 'Outdoor', rating: '4.8' },
  { id: 5, name: 'Knee Compression Sleeve', category: 'Protection', price: 9000, image: '/images/best-sleeves.png', size: 'S / M / L', purpose: 'Training', rating: '4.8' },
  { id: 6, name: 'Court Jersey', category: 'Apparel', price: 18900, image: '/images/collection-apparel.png', size: 'S / M / L', purpose: 'Training', rating: '4.7' },
]
const screen = ref<Screen>('login')
const previousScreen = ref<Screen>('home')
const selected = ref<Product>(products[0])
const cart = ref<Product[]>([products[3], products[1], products[4]])
const cartOpen = ref(false)
const paying = ref(false)
const favorites = ref<number[]>([])
const menuOpen = ref(false)
const query = ref('')
const searchOpen = ref(false)
const collectionProducts = computed(() => [products[4], products[1], products[0], products[2], products[5]].filter((p): p is Product => Boolean(p)).filter(p => p.name.toLowerCase().includes(query.value.toLowerCase())))
const fmt = (price: number) => new Intl.NumberFormat('ru-RU').format(price)
const collectionImage = (product: Product) => product.id === 5 ? '/images/collection-leggings.png' : product.id === 2 ? '/images/collection-socks.png' : product.id === 1 ? '/images/collection-asphalt.png' : product.id === 3 ? '/images/collection-pechenka.png' : product.id === 6 ? '/images/collection-apparel.png' : product.image
const cartImage = (product: Product) => product.id === 4 ? '/images/cart-wave.jpg' : product.id === 2 ? '/images/cart-socks.jpg' : product.id === 5 ? '/images/cart-sleeve.jpg' : product.image
const checkoutItems = computed(() => cart.value.length >= 3 ? [cart.value[0], cart.value[2], cart.value[1], ...cart.value.slice(3)] : cart.value)
function openProduct(product: Product) { previousScreen.value = screen.value; selected.value = product; screen.value = 'product'; window.scrollTo({ top: 0, behavior: 'smooth' }) }
function addToCart(product: Product, open = true) { cart.value.push(product); if (open) screen.value = 'cart'; window.scrollTo({ top: 0 }) }
function toggleFavorite(id: number) { favorites.value = favorites.value.includes(id) ? favorites.value.filter(item => item !== id) : [...favorites.value, id] }
function payOrder() { if (!cart.value.length) return; paying.value = true; cart.value = []; previousScreen.value = 'home'; window.setTimeout(() => { paying.value = false; screen.value = 'profile'; window.scrollTo({ top: 0 }) }, 850) }
function go(next: Screen) { previousScreen.value = screen.value; screen.value = next; menuOpen.value = false; window.scrollTo({ top: 0, behavior: 'smooth' }) }
function back() { screen.value = previousScreen.value === 'home' || previousScreen.value === 'login' ? 'home' : previousScreen.value; window.scrollTo({ top: 0, behavior: 'smooth' }) }
function scrollToProducts() { document.getElementById('new-collection')?.scrollIntoView({ behavior: 'smooth' }) }
</script>

